"use client";

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical";
import { DecoratorNode } from "lexical";
import type { JSX } from "react";

import { MathComponent } from "../../../plugins/math/component";

export type SerializedMathNode = Spread<
  {
    equation: string;
    inline: boolean;
  },
  SerializedLexicalNode
>;

export interface MathPayload {
  equation: string;
  inline?: boolean;
  key?: NodeKey;
}

const convertMathElement = (domNode: Node): DOMConversionOutput | null => {
  if (!(domNode instanceof HTMLElement)) {
    return null;
  }

  const { equation } = domNode.dataset;
  if (equation === undefined) {
    return null;
  }

  const inline = domNode.dataset.inline !== "false";

  return {
    node: $createMathNode({
      equation,
      inline,
    }),
  };
};

export class MathNode extends DecoratorNode<JSX.Element> {
  __equation: string;
  __inline: boolean;

  constructor(equation: string, inline = true, key?: NodeKey) {
    super(key);
    this.__equation = equation;
    this.__inline = inline;
  }

  static getType(): string {
    return "math";
  }

  static clone(node: MathNode): MathNode {
    return new MathNode(node.__equation, node.__inline, node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: Node) => {
        if (
          domNode instanceof HTMLElement &&
          Object.hasOwn(domNode.dataset, "equation")
        ) {
          return {
            conversion: convertMathElement,
            priority: 2,
          };
        }
        return null;
      },
      span: (domNode: Node) => {
        if (
          domNode instanceof HTMLElement &&
          Object.hasOwn(domNode.dataset, "equation")
        ) {
          return {
            conversion: convertMathElement,
            priority: 2,
          };
        }
        return null;
      },
    };
  }

  static importJSON(serializedNode: SerializedMathNode): MathNode {
    return $createMathNode({
      equation: serializedNode.equation,
      inline: serializedNode.inline,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(serializedNode: LexicalUpdateJSON<SerializedMathNode>): this {
    return super
      .updateFromJSON(serializedNode)
      .setEquation(serializedNode.equation)
      .setInline(serializedNode.inline);
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement(this.__inline ? "span" : "div");
    element.dataset.lexicalMath = "true";
    element.dataset.equation = this.__equation;
    element.dataset.inline = this.__inline ? "true" : "false";
    element.textContent = this.__equation;
    return { element };
  }

  exportJSON(): SerializedMathNode {
    return {
      ...super.exportJSON(),
      equation: this.__equation,
      inline: this.__inline,
      type: "math",
      version: 1,
    };
  }

  createDOM(config: EditorConfig): HTMLElement {
    const element = document.createElement(this.__inline ? "span" : "div");

    if (typeof config.theme.math === "string") {
      addClassNamesToElement(element, config.theme.math);
    }

    addClassNamesToElement(
      element,
      this.__inline
        ? "inline-block cursor-pointer select-none"
        : "block my-2 cursor-pointer select-none text-center"
    );

    return element;
  }

  updateDOM(prevNode: MathNode): boolean {
    return this.__inline !== prevNode.__inline;
  }

  getTextContent(): string {
    return this.__equation;
  }

  decorate(): JSX.Element {
    return (
      <MathComponent
        equation={this.__equation}
        inline={this.__inline}
        nodeKey={this.getKey()}
      />
    );
  }

  isInline(): boolean {
    return this.__inline;
  }

  getEquation(): string {
    return this.getLatest().__equation;
  }

  setEquation(equation: string): this {
    const writable = this.getWritable();
    writable.__equation = equation;
    return writable;
  }

  getInline(): boolean {
    return this.getLatest().__inline;
  }

  setInline(inline: boolean): this {
    const writable = this.getWritable();
    writable.__inline = inline;
    return writable;
  }
}

export function $createMathNode({
  equation,
  inline = true,
  key,
}: MathPayload): MathNode {
  return new MathNode(equation, inline, key);
}

export function $isMathNode(
  node: LexicalNode | null | undefined
): node is MathNode {
  return node instanceof MathNode;
}

import type {
  MultilineElementTransformer,
  TextMatchTransformer,
} from "@lexical/markdown";

import { $createMathNode, $isMathNode, MathNode } from "./node";

// Requires non-whitespace directly inside both delimiters and rejects a digit
// right after the closing `$`, preventing currency strings like "$5 and $10"
// from being parsed as inline math while preserving "$x$" and "$E = mc^2$".
const INLINE_MATH_REGEXP = /\$(?<equation>[^\s$](?:[^$]*[^\s$])?)\$(?!\d)/u;

export const MATH_INLINE_MARKDOWN_TRANSFORMER: TextMatchTransformer = {
  dependencies: [MathNode],
  export: (node) => {
    if (!($isMathNode(node) && node.getInline())) {
      return null;
    }
    return `$${node.getEquation()}$`;
  },
  importRegExp: INLINE_MATH_REGEXP,
  regExp: INLINE_MATH_REGEXP,
  replace: (node, match) => {
    const equation = match.groups?.equation;
    if (!equation) {
      return;
    }
    node.replace($createMathNode({ equation, inline: true }));
  },
  trigger: "$",
  type: "text-match",
};

export const MATH_BLOCK_MARKDOWN_TRANSFORMER: MultilineElementTransformer = {
  dependencies: [MathNode],
  export: (node) => {
    if (!$isMathNode(node) || node.getInline()) {
      return null;
    }
    return `$$\n${node.getEquation()}\n$$`;
  },
  handleImportAfterStartMatch: ({ lines, rootNode, startLineIndex }) => {
    const startLine = lines[startLineIndex]?.trim();
    if (!startLine) {
      return null;
    }

    if (
      startLine.startsWith("$$") &&
      startLine.endsWith("$$") &&
      startLine.length > 4
    ) {
      const equation = startLine.slice(2, -2).trim();
      rootNode.append($createMathNode({ equation, inline: false }));
      return [true, startLineIndex];
    }

    if (startLine !== "$$") {
      return null;
    }

    const equationLines: string[] = [];
    let lineIndex = startLineIndex + 1;
    let foundClosing = false;

    while (lineIndex < lines.length) {
      const line = lines[lineIndex] ?? "";
      if (line.trim() === "$$") {
        foundClosing = true;
        break;
      }
      equationLines.push(line);
      lineIndex += 1;
    }

    if (!foundClosing) {
      return null;
    }

    const equation = equationLines.join("\n").trim();
    rootNode.append($createMathNode({ equation, inline: false }));
    return [true, lineIndex];
  },
  regExpEnd: {
    optional: true,
    regExp: /^\$\$\s*$/u,
  },
  regExpStart: /^\$\$/u,
  replace: () => false,
  type: "multiline-element",
};

import { createCommand } from "lexical";
import type { LexicalCommand } from "lexical";

import type { MathPayload } from "../../core/nodes/math/node";

export const INSERT_MATH_COMMAND: LexicalCommand<MathPayload> = createCommand(
  "INSERT_MATH_COMMAND"
);

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { $insertNodeToNearestRoot, mergeRegister } from "@lexical/utils";
import { renderToString } from "katex";

import "katex/dist/katex.min.css";
import {
  $createParagraphNode,
  $getNodeByKey,
  $getSelection,
  $isNodeSelection,
  $isParagraphNode,
  $isRootNode,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
} from "lexical";
import type { NodeKey } from "lexical";
import { CheckIcon, Trash2Icon } from "lucide-react";
import type { RefObject } from "react";
import { useEffect, useRef, useState } from "react";

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";

import { $isMathNode } from "../../core/nodes/math/node";

interface MathComponentProps {
  equation: string;
  inline: boolean;
  nodeKey: NodeKey;
}

const KATEX_MAX_SIZE = 20;

const escapeHtml = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

const renderEquationHtml = (source: string, displayMode: boolean): string => {
  const value = source || "\\text{math}";
  try {
    return renderToString(value, {
      displayMode,
      errorColor: "var(--destructive, #cc0000)",
      maxSize: KATEX_MAX_SIZE,
      throwOnError: false,
    });
  } catch {
    return `<span class="text-destructive">${escapeHtml(source || "math")}</span>`;
  }
};

interface MathEditorPopoverBodyProps {
  draftEquation: string;
  draftInline: boolean;
  onCancel: () => void;
  onDelete: () => void;
  onDraftEquationChange: (value: string) => void;
  onDraftInlineChange: (value: boolean) => void;
  onSave: () => void;
  previewHtml: string;
  textareaRef: RefObject<HTMLTextAreaElement | null>;
}

function MathEditorPopoverBody({
  draftEquation,
  draftInline,
  onCancel,
  onDelete,
  onDraftEquationChange,
  onDraftInlineChange,
  onSave,
  previewHtml,
  textareaRef,
}: MathEditorPopoverBodyProps) {
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between text-xs font-medium text-muted-foreground">
        <span>Edit TeX equation</span>
        <div className="editor-math-segment flex items-center gap-1">
          <button
            aria-pressed={draftInline}
            className={cn(
              "rounded px-2 py-0.5 text-xs font-medium transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
              draftInline
                ? "bg-background text-foreground shadow-xs"
                : "text-muted-foreground hover:text-foreground"
            )}
            onClick={() => onDraftInlineChange(true)}
            type="button"
          >
            Inline
          </button>
          <button
            aria-pressed={!draftInline}
            className={cn(
              "rounded px-2 py-0.5 text-xs font-medium transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
              draftInline
                ? "text-muted-foreground hover:text-foreground"
                : "bg-background text-foreground shadow-xs"
            )}
            onClick={() => onDraftInlineChange(false)}
            type="button"
          >
            Block
          </button>
        </div>
      </div>

      <textarea
        aria-label="TeX equation"
        className="w-full rounded-md border border-input bg-background px-3 py-1.5 font-mono text-xs ring-offset-background placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
        onChange={(event) => onDraftEquationChange(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
            event.preventDefault();
            onSave();
          } else if (event.key === "Escape") {
            event.preventDefault();
            onCancel();
          }
        }}
        placeholder="e.g. f(x) = x^2"
        ref={textareaRef}
        rows={2}
        value={draftEquation}
      />

      <div className="editor-math-preview">
        <ScrollArea>
          <div className="flex items-center justify-center">
            <span dangerouslySetInnerHTML={{ __html: previewHtml }} />
          </div>
        </ScrollArea>
      </div>

      <div className="flex items-center justify-between pt-2">
        <button
          className="inline-flex items-center gap-1 rounded px-2 py-1 text-xs font-medium text-destructive transition-colors hover:bg-destructive/10 hover:text-destructive/80 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
          onClick={onDelete}
          type="button"
        >
          <Trash2Icon aria-hidden className="size-3.5" />
          Remove
        </button>

        <div className="flex items-center gap-1.5">
          <button
            className="rounded px-2.5 py-1 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
            onClick={onCancel}
            type="button"
          >
            Cancel
          </button>
          <button
            className="inline-flex items-center gap-1 rounded bg-primary px-2.5 py-1 text-xs font-medium text-primary-foreground shadow-xs transition-colors hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
            onClick={onSave}
            type="button"
          >
            <CheckIcon aria-hidden className="size-3.5" />
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

export function MathComponent({
  equation,
  inline,
  nodeKey,
}: MathComponentProps) {
  const [editor] = useLexicalComposerContext();
  const editable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const [isEditing, setIsEditing] = useState(false);
  const [draftEquation, setDraftEquation] = useState(equation);
  const [draftInline, setDraftInline] = useState(inline);
  const mathRef = useRef<HTMLSpanElement | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  const openEditor = () => {
    setDraftEquation(equation);
    setDraftInline(inline);
    setIsEditing(true);
  };

  const closeEditor = () => {
    setIsEditing(false);
    requestAnimationFrame(() => {
      triggerRef.current?.focus({ preventScroll: true });
    });
  };

  useEffect(() => {
    if (!isEditing) {
      return;
    }
    const timer = window.setTimeout(() => {
      textareaRef.current?.focus({ preventScroll: true });
    }, 0);
    return () => window.clearTimeout(timer);
  }, [isEditing]);

  const html = renderEquationHtml(equation, !inline);
  const previewHtml = renderEquationHtml(draftEquation, !draftInline);

  useEffect(() => {
    if (!editable) {
      return;
    }

    const removeNode = (event: KeyboardEvent) => {
      const selection = $getSelection();
      if (!(isSelected && $isNodeSelection(selection))) {
        return false;
      }

      event.preventDefault();
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isMathNode(node)) {
          node.remove();
        }
      });
      return true;
    };

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event) => {
          if (mathRef.current?.contains(event.target as Node)) {
            if (event.shiftKey) {
              setSelected(!isSelected);
            } else {
              clearSelection();
              setSelected(true);
            }
            return true;
          }
          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        removeNode,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_DELETE_COMMAND,
        removeNode,
        COMMAND_PRIORITY_LOW
      )
    );
  }, [clearSelection, editable, editor, isSelected, nodeKey, setSelected]);

  const handleSave = () => {
    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if (!$isMathNode(node)) {
        return;
      }

      const wasInline = node.getInline();
      node.setEquation(draftEquation);

      if (wasInline === draftInline) {
        return;
      }

      node.setInline(draftInline);
      const parent = node.getParent();

      if (draftInline) {
        if (!(parent && $isParagraphNode(parent))) {
          const paragraph = $createParagraphNode();
          node.replace(paragraph);
          paragraph.append(node);
        }
      } else if (parent && $isParagraphNode(parent)) {
        const grandParent = parent.getParent();
        if (
          grandParent &&
          $isRootNode(grandParent) &&
          parent.getChildrenSize() === 1
        ) {
          parent.replace(node);
        } else {
          node.remove();
          $insertNodeToNearestRoot(node);
        }
        if (!node.getNextSibling()) {
          node.insertAfter($createParagraphNode());
        }
      }
    });
    setIsEditing(false);

    clearSelection();
    setSelected(true);
    requestAnimationFrame(() => {
      editor.getRootElement()?.focus({ preventScroll: true });
    });
  };

  const handleDelete = () => {
    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if ($isMathNode(node)) {
        node.remove();
      }
    });
    setIsEditing(false);
    requestAnimationFrame(() => {
      editor.getRootElement()?.focus({ preventScroll: true });
    });
  };

  if (!editable) {
    return (
      <span
        className={cn(
          "relative inline-block align-middle",
          !inline && "editor-math-block"
        )}
        ref={mathRef}
      >
        <span
          className="editor-math-trigger inline-block"
          dangerouslySetInnerHTML={{ __html: html }}
        />
      </span>
    );
  }

  return (
    <span
      className={cn(
        "relative inline-block align-middle",
        !inline && "editor-math-block"
      )}
      ref={mathRef}
    >
      <Popover
        onOpenChange={(open) => {
          if (open) {
            openEditor();
          } else {
            closeEditor();
          }
        }}
        open={isEditing}
      >
        <PopoverTrigger
          render={
            <button
              aria-label={
                equation ? `Edit equation: ${equation}` : "Edit TeX equation"
              }
              className={cn(
                "editor-math-trigger appearance-none border-0 bg-transparent p-0 text-inherit transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                isSelected && "editor-math-trigger-selected",
                "cursor-pointer hover:bg-muted/40"
              )}
              dangerouslySetInnerHTML={{ __html: html }}
              ref={triggerRef}
              title="Edit TeX equation"
              type="button"
            />
          }
        />

        <PopoverContent
          align="center"
          className="editor-floating w-72 p-3"
          initialFocus={false}
          side="bottom"
          sideOffset={4}
        >
          <MathEditorPopoverBody
            draftEquation={draftEquation}
            draftInline={draftInline}
            onCancel={closeEditor}
            onDelete={handleDelete}
            onDraftEquationChange={setDraftEquation}
            onDraftInlineChange={setDraftInline}
            onSave={handleSave}
            previewHtml={previewHtml}
            textareaRef={textareaRef}
          />
        </PopoverContent>
      </Popover>
    </span>
  );
}

import { $createParagraphNode } from "lexical";
import type { ElementNode } from "lexical";
import { CalculatorIcon } from "lucide-react";

import { $createMathNode, MathNode } from "../../core/nodes/math/node";
import {
  MATH_BLOCK_MARKDOWN_TRANSFORMER,
  MATH_INLINE_MARKDOWN_TRANSFORMER,
} from "../../core/nodes/math/transformers";
import type { ExtraEditorFeature } from "../../core/types";
import { replaceCurrentBlock } from "../slash-command/utils";
import { MathPlugin } from "./plugin";

const applyMathCommand = (targetElement: ElementNode): void => {
  const mathNode = $createMathNode({
    equation: "f(x) = c",
    inline: false,
  });
  const paragraph = $createParagraphNode();

  targetElement.replace(mathNode);
  mathNode.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Installs the math feature: the `MathNode`, KaTeX rendering, the `$...$` /
 * `$$...$$` markdown transformers and the shared insert-menu entry. Ships as
 * the `editor-math` registry item and pulls `katex`.
 */
export const mathFeature: ExtraEditorFeature = {
  id: "math",
  nodes: [MathNode],
  plugin: MathPlugin,
  slashCommands: [
    {
      command: {
        description: "Insert TeX math equation",
        icon: CalculatorIcon,
        id: "math",
        keywords: ["math", "latex", "katex", "equation", "formula", "tex"],
        label: "Math Block",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyMathCommand);
      },
    },
  ],
  transformers: [
    MATH_INLINE_MARKDOWN_TRANSFORMER,
    MATH_BLOCK_MARKDOWN_TRANSFORMER,
  ],
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $insertNodeToNearestRoot, mergeRegister } from "@lexical/utils";
import {
  $getSelection,
  $insertNodes,
  $isRangeSelection,
  COMMAND_PRIORITY_EDITOR,
} from "lexical";
import { useEffect } from "react";

import { $createMathNode } from "../../core/nodes/math/node";
import type { MathPayload } from "../../core/nodes/math/node";
import { INSERT_MATH_COMMAND } from "./commands";

export function MathPlugin(): null {
  const [editor] = useLexicalComposerContext();

  useEffect(
    () =>
      mergeRegister(
        editor.registerCommand<MathPayload>(
          INSERT_MATH_COMMAND,
          (payload) => {
            const { equation, inline = true } = payload;
            const mathNode = $createMathNode({ equation, inline });

            const selection = $getSelection();
            if ($isRangeSelection(selection)) {
              if (inline) {
                $insertNodes([mathNode]);
              } else {
                $insertNodeToNearestRoot(mathNode);
              }
            } else {
              $insertNodes([mathNode]);
            }

            return true;
          },
          COMMAND_PRIORITY_EDITOR
        )
      ),
    [editor]
  );

  return null;
}
